list_dashboard_banners.code:
var response = await client.DashboardBanners.ListDashboardBannersAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var banner in ((IReadOnlyList<object?>)body["banners"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{banner["key"]} {banner["position"]} {banner["active"]} {banner["title"]}");

